<template><main class="page"><header><h1>Items</h1><nav><RouterLink to="/checkout">Checkout</RouterLink> · <RouterLink to="/borrowers">Borrowers</RouterLink> · <RouterLink to="/settings">Settings</RouterLink></nav></header><p v-if="loading">Loading…</p><p v-else-if="error" class="error">{{ error }}</p><table v-else><thead><tr><th>Name</th><th>Barcode</th><th>Status</th></tr></thead><tbody><tr v-for="item in items" :key="item.id"><td>{{ item.name }}</td><td>{{ item.barcode }}</td><td>{{ item.status }}</td></tr></tbody></table></main></template>
<script setup lang="ts">import{onMounted,ref}from"vue";import{RouterLink}from"vue-router";import{authenticatedSelect}from"../../services/authenticatedDataClient";type Row={id:string;name:string;barcode:string;status:string};const items=ref<Row[]>([]),loading=ref(true),error=ref("");onMounted(async()=>{try{items.value=await authenticatedSelect<Row[]>("gear",{select:"id,name,barcode,status",deleted_at:"is.null",order:"name.asc"});}catch{error.value="Unable to load items."}finally{loading.value=false;}});</script>
